    g_hero_r.reach_height = 1.25f;
    g_hero_r.health.vehicle_mode_hp = 4;
    g_hero_r.health.unk22B0 = g_hero_r.health.hp;
    g_hero_r.unk1010 = rand_range(scale_ticks(0xB4), scale_ticks(0x12C));
